#!/usr/bin/env python3
"""تولید صفحات پیوست «ثبت جامع تغییرات» (21-26) از دادهٔ ساختاریافته."""
from pathlib import Path

HERE = Path(__file__).resolve().parent
PAGES = HERE / "pages"
FD = ["\u06F0","\u06F1","\u06F2","\u06F3","\u06F4","06F5".replace("06","6F"),"06F6".replace("06","6F"),"06F7".replace("06","6F"),"06F8".replace("06","6F"),"06F9".replace("06","6F")]
FD = ["\u06F0","\u06F1","\u06F2","\u06F3","\u06F4","\u06F5","\u06F6","\u06F7","\u06F8","\u06F9"]
ar = lambda s: ''.join(FD[int(c)] for c in s)

def header_block(title, part):
    return f"""  <div class="a4-content" style="gap:4mm">
    <div>
      <div class="af-eyebrow"><span class="n">۱۳</span> ۱۳ — پیوست، ثبت جامع تغییرات {part}</div>
      <h2 class="af-h2">{title}</h2>
    </div>
"""

def row(no, idtag, area, files, issue, change, status):
    no_fa = ar(str(no))
    return f"""          <tr>
            <td class="td-id"><span class="idtag">{idtag}</span><small>ردیف {no_fa}</small></td>
            <td class="td-bold">{area}</td>
            <td class="refs"><span class="path">{files}</span></td>
            <td>{issue}</td>
            <td>{change}</td>
            <td>{status}</td>
          </tr>"""

THEAD = """        <thead><tr>
          <th style="width:9%">شناسه</th><th style="width:8%">زیرسامنه</th><th style="width:26%">فایل / نماد / خط</th>
          <th style="width:19%">مسئله یا ریسک هدف</th><th style="width:28%">تغییر و رفتار مورد انتظار</th><th style="width:10%">تست و ملاحظه</th>
        </tr></thead>
        <tbody>
"""

FOOTER_NOTE = """    <div class="af-caption af-push" style="border-top:1px solid var(--af-ink-10);padding-top:2mm">
      وضعیت تستِ همهٔ ردیف‌های این ثبت: <b>بررسی و تست‌شده توسط تیم فنی + تست میدانی نسخه‌به‌نسخه</b> (ثبت‌شده به‌صورت «تست: میدانی» در دفتر). ارجاع‌ها: «new» = نسخهٔ فعلی <span class="af-ltr">B1.06.60</span>، «old» = نسخهٔ تحویلی <span class="af-ltr">B1.05.20</span>.
    </div>
  </div>
"""

def page(fname, part, title, rows):
    body = [header_block(title, part)]
    body.append('    <div class="af-table-wrap reg">\n      <table class="af-table">\n' + THEAD)
    for i, r in enumerate(rows, 1):
        body.append(row(i, *r))
    body.append("        </tbody>\n      </table>\n    </div>")
    body.append(FOOTER_NOTE)
    (PAGES / fname).write_text("\n".join(body) + "\n", encoding="utf-8")
    print("wrote", fname, len(rows), "rows")


